import { createHash } from 'node:crypto';
import { existsSync, mkdirSync, readFileSync, readdirSync, rmdirSync, rmSync, statSync, writeFileSync } from 'node:fs';
import { dirname, isAbsolute, join, relative, resolve, sep } from 'node:path';
import {
  checkThirdPartyKit, declareThirdPartyKit, removeThirdPartyKit, thirdPartyIssues, thirdPartyKits, thirdPartyModuleEntry, thirdPartyModuleFile, thirdPartySummary,
  type KitModulesIndex, type ThirdPartyGame, type ThirdPartyKitDecl, type ThirdPartyKitManifest,
} from './third-party.generated.js';

const MAX_MODULE = 64 * 1024 * 1024;
/** Where a module given as a file is copied, beside the game file: the game folder stays complete by itself. */
export const THIRD_PARTY_DIR = 'third-party-kits';
const isUrl = (source: string) => /^https?:\/\//i.test(source);
const sha256 = (bytes: Uint8Array) => createHash('sha256').update(bytes).digest('hex');
const posix = (path: string) => path.split(sep).join('/');

export interface GameFiles { file: string; dir: string; game: ThirdPartyGame; modulesDir: string | null; modules: KitModulesIndex | null }

/** The game file and, when the game has them, its kit modules. */
export function openGame(path: string, modulesDir?: string): GameFiles {
  if (!path) throw Error('A game is needed: the path of a game.json, or of the folder that holds it.');
  let file = resolve(path);
  if (existsSync(file) && statSync(file).isDirectory()) file = join(file, 'game.json');
  if (!existsSync(file)) throw Error(`${file}: no such game file. A game is a game.json ({ "project": …, "lock": … }) or the folder that holds it (gripforge game-export <gkp_id> <folder> makes one).`);
  let game: ThirdPartyGame;
  try { game = JSON.parse(readFileSync(file, 'utf8')) as ThirdPartyGame; } catch (error) { throw Error(`${file}: not JSON (${(error as Error).message})`); }
  if (!game || typeof game !== 'object' || !game.project || typeof game.project !== 'object' || !Array.isArray(game.lock?.order)) throw Error(`${file}: a game file is { "project": { "installed": […] }, "lock": { "order": [kit ids] } }`);
  const dir = dirname(file);
  const candidates = modulesDir ? [resolve(modulesDir)] : [join(dir, 'runtime-rust/kit-modules'), join(dir, 'kit-modules')];
  const found = candidates.find((d) => existsSync(join(d, 'kit-modules.json'))) ?? null;
  if (modulesDir && !found) throw Error(`${resolve(modulesDir)}: no kit-modules.json — --modules must be a folder of kit modules`);
  const modules = found ? JSON.parse(readFileSync(join(found, 'kit-modules.json'), 'utf8')) as KitModulesIndex : null;
  return { file, dir, game, modulesDir: found, modules };
}

function saveGame(files: GameFiles, game: ThirdPartyGame) { writeFileSync(files.file, `${JSON.stringify(game, null, 2)}\n`); }

/** The bytes of a module or a manifest: a file (relative to `base`) or an http(s) URL. */
export async function readSource(source: string, base: string, signal?: AbortSignal): Promise<Uint8Array> {
  if (isUrl(source)) {
    const response = await fetch(source, { redirect: 'follow', signal: signal ? AbortSignal.any([signal, AbortSignal.timeout(60_000)]) : AbortSignal.timeout(60_000) });
    if (!response.ok) throw Error(`${source}: HTTP ${response.status}`);
    const bytes = new Uint8Array(await response.arrayBuffer());
    if (bytes.length > MAX_MODULE) throw Error(`${source}: ${bytes.length} bytes, more than the ${MAX_MODULE} allowed`);
    return bytes;
  }
  if (/^[a-z][a-z0-9+.-]*:\/\//i.test(source)) throw Error(`${source}: only a file path or an http(s) URL`);
  const path = isAbsolute(source) ? source : resolve(base, source);
  if (!existsSync(path)) throw Error(`${path}: no such file`);
  const bytes = readFileSync(path);
  if (bytes.length > MAX_MODULE) throw Error(`${path}: ${bytes.length} bytes, more than the ${MAX_MODULE} allowed`);
  return bytes;
}

/** Puts a declared module in the folder of kit modules (file named by its hash, its line in kit-modules.json). */
function installModule(files: GameFiles, decl: ThirdPartyKitDecl, bytes: Uint8Array): string | null {
  if (!files.modulesDir || !files.modules) return null;
  const previous = files.modules.kits?.[decl.id], file = thirdPartyModuleFile(decl.id, decl.sha256);
  if (previous?.thirdParty && previous.wasm && previous.wasm !== file) rmSync(join(files.modulesDir, previous.wasm), { force: true });
  writeFileSync(join(files.modulesDir, file), bytes);
  files.modules = { ...files.modules, kits: { ...(files.modules.kits ?? {}), [decl.id]: thirdPartyModuleEntry(decl) } };
  writeFileSync(join(files.modulesDir, 'kit-modules.json'), JSON.stringify(files.modules, null, 1));
  return join(files.modulesDir, file);
}

export interface AddKitOptions { game: string; wasm: string; manifest: string; config?: Record<string, unknown>; modules?: string; check?: boolean; cwd?: string; signal?: AbortSignal }
export interface AddKitReport { game: string; id: string; version: string; source: string; sha256: string; bytes: number; replaced: boolean; checked: boolean; module: string | null; modules: string | null; warnings: string[]; order: string[] }

/**
 * Declares a third-party kit in a game: reads the module and its manifest, checks them (against each other, against
 * the kit modules of the game when it has them, against the kits the game installs), then writes the declaration,
 * the `installed` entry and the lock lines. `check`: everything but the writes.
 */
export async function addKit(options: AddKitOptions): Promise<AddKitReport> {
  const cwd = options.cwd ?? process.cwd(), files = openGame(isAbsolute(options.game) ? options.game : resolve(cwd, options.game), options.modules ? resolve(cwd, options.modules) : undefined);
  if (!options.wasm) throw Error('--wasm is needed: the kit module (a .wasm file or an http(s) URL).');
  if (!options.manifest) throw Error('--manifest is needed: the kit.json of the kit (a file or an http(s) URL).');
  const bytes = await readSource(options.wasm, cwd, options.signal);
  let manifest: ThirdPartyKitManifest;
  try { manifest = JSON.parse(new TextDecoder().decode(await readSource(options.manifest, cwd, options.signal))) as ThirdPartyKitManifest; } catch (error) { throw Error(`${options.manifest}: ${(error as Error).message}`); }
  const reserved = (id: string) => !!files.modules?.kits?.[id] && !files.modules.kits[id]!.thirdParty;
  const check = checkThirdPartyKit({ manifest, wasm: bytes, modules: files.modules, reserved });
  if (check.issues.length) throw Error(check.issues.join('\n'));
  const digest = sha256(bytes), replaced = thirdPartyKits(files.game.project).some((k) => k.id === manifest.id);
  const vendored = `${THIRD_PARTY_DIR}/${manifest.id}-${manifest.version}.wasm`;
  const source = isUrl(options.wasm) ? options.wasm : `./${vendored}`;
  const decl: ThirdPartyKitDecl = { id: manifest.id, version: manifest.version, source, sha256: digest, bytes: bytes.length, manifest };
  const game = declareThirdPartyKit(files.game, decl, { config: options.config });
  const issues = thirdPartyIssues(game);
  if (issues.length) throw Error(issues.join('\n'));
  let module: string | null = null;
  if (!options.check) {
    if (!isUrl(options.wasm)) {
      const before = thirdPartyKits(files.game.project).find((k) => k.id === manifest.id)?.source;
      if (before && before !== source && before.startsWith(`./${THIRD_PARTY_DIR}/`)) rmSync(join(files.dir, before), { force: true });
      mkdirSync(join(files.dir, THIRD_PARTY_DIR), { recursive: true });
      writeFileSync(join(files.dir, vendored), bytes);
    }
    module = installModule(files, decl, bytes);
    saveGame(files, game);
  }
  if (!files.modules) check.warnings.push('this game has no kit modules beside it (no runtime-rust/kit-modules/ or kit-modules/ with a kit-modules.json): the kit was checked against its manifest only. Pass --modules <folder of kit modules> to check it against a core now; the web export checks it in any case');
  return { game: files.file, id: decl.id, version: decl.version, source, sha256: digest, bytes: bytes.length, replaced, checked: !!options.check, module, modules: files.modulesDir, warnings: check.warnings, order: game.lock.order ?? [] };
}

export interface VerifyKitReport { game: string; ok: boolean; modules: string | null; kits: Array<{ id: string; version: string; source: string; sha256: string; ok: boolean; issues: string[]; warnings: string[] }>; issues: string[] }

/**
 * Verifies the declared third-party kits of a game (one with `id`): each module is read again from its source and
 * must have the SHA-256 the game declares and its lock froze; its manifest must still be what the binary says; the
 * declaration, `installed`, the lock and the kit modules of the game must agree on the version.
 */
export async function verifyKits(options: { game: string; id?: string; modules?: string; cwd?: string; signal?: AbortSignal }): Promise<VerifyKitReport> {
  const cwd = options.cwd ?? process.cwd(), files = openGame(isAbsolute(options.game) ? options.game : resolve(cwd, options.game), options.modules ? resolve(cwd, options.modules) : undefined);
  const declared = thirdPartyKits(files.game.project);
  if (options.id && !declared.some((k) => k.id === options.id)) throw Error(`${options.id} is not a declared third-party kit of this game (declared: ${declared.map((k) => k.id).join(', ') || 'none'})`);
  const all = thirdPartyIssues(files.game, { modules: files.modules });
  const kits: VerifyKitReport['kits'] = [];
  for (const decl of declared.filter((k) => !options.id || k.id === options.id)) {
    const issues = all.filter((line) => line.startsWith(`${decl.id}: `)).map((line) => line.slice(decl.id.length + 2)), warnings: string[] = [];
    try {
      const bytes = await readSource(decl.source, files.dir, options.signal), digest = sha256(bytes);
      if (digest !== decl.sha256) issues.push(`the module at ${decl.source} has sha256 ${digest}, the game declares ${decl.sha256}: it is not the binary that was declared (add it again to accept the new one)`);
      else {
        const check = checkThirdPartyKit({ manifest: decl.manifest, wasm: bytes, modules: files.modules });
        issues.push(...check.issues); warnings.push(...check.warnings);
      }
    } catch (error) { issues.push(`the module cannot be read: ${(error as Error).message}`); }
    const entry = files.modules?.kits?.[decl.id];
    if (files.modulesDir && entry?.wasm) {
      const path = join(files.modulesDir, entry.wasm);
      if (!existsSync(path)) issues.push(`kit-modules.json names ${entry.wasm}, which is not in ${files.modulesDir}`);
      else { const found = sha256(readFileSync(path)); if (found !== decl.sha256) issues.push(`the kit module ${entry.wasm} has sha256 ${found}, the game declares ${decl.sha256}: the kit modules do not hold the declared binary (gripforge kit add puts it there again)`); }
    }
    kits.push({ id: decl.id, version: decl.version, source: decl.source, sha256: decl.sha256, ok: !issues.length, issues, warnings });
  }
  const rest = options.id ? [] : all.filter((line) => !declared.some((k) => line.startsWith(`${k.id}: `)));
  return { game: files.file, ok: kits.every((k) => k.ok) && !rest.length, modules: files.modulesDir, kits, issues: rest };
}

/** The declared third-party kits of a game. */
export function listKits(options: { game: string; cwd?: string }) {
  const files = openGame(isAbsolute(options.game) ? options.game : resolve(options.cwd ?? process.cwd(), options.game));
  return { game: files.file, modules: files.modulesDir, kits: thirdPartySummary(files.game) };
}

/** Removes a declared third-party kit: the declaration, `installed`, the lock, the copy of its module and its kit module. */
export function removeKit(options: { game: string; id: string; modules?: string; cwd?: string }) {
  const cwd = options.cwd ?? process.cwd(), files = openGame(isAbsolute(options.game) ? options.game : resolve(cwd, options.game), options.modules ? resolve(cwd, options.modules) : undefined);
  const decl = thirdPartyKits(files.game.project).find((k) => k.id === options.id);
  const game = removeThirdPartyKit(files.game, options.id);
  const removed: string[] = [];
  if (decl && decl.source.startsWith(`./${THIRD_PARTY_DIR}/`) && !decl.source.includes('..')) { const path = join(files.dir, decl.source); if (existsSync(path)) { rmSync(path); removed.push(posix(relative(files.dir, path))); } }
  // The folder of the copies goes with its last file (never a folder that holds something else).
  try { const copies = join(files.dir, THIRD_PARTY_DIR); if (existsSync(copies) && !readdirSync(copies).length) rmdirSync(copies); } catch { /* left as it is */ }
  const entry = files.modules?.kits?.[options.id];
  if (files.modulesDir && files.modules && entry?.thirdParty) {
    if (entry.wasm) { rmSync(join(files.modulesDir, entry.wasm), { force: true }); removed.push(posix(relative(files.dir, join(files.modulesDir, entry.wasm)))); }
    const { [options.id]: _gone, ...kits } = files.modules.kits ?? {};
    writeFileSync(join(files.modulesDir, 'kit-modules.json'), JSON.stringify({ ...files.modules, kits }, null, 1));
  }
  saveGame(files, game);
  const dependents = thirdPartyKits(game.project).filter((k) => (k.manifest.requires ?? []).some((r) => r.split('@')[0] === options.id)).map((k) => k.id);
  return { game: files.file, id: options.id, removed, order: game.lock.order ?? [], dependents };
}

